import sqlite3
import json

def get_map_data(db_path):
    conn = sqlite3.connect(db_path)
    conn.row_factory = sqlite3.Row
    cursor = conn.cursor()

    cursor.execute("SELECT Width, Height FROM Map")
    row = cursor.fetchone()
    width = row["Width"]
    height = row["Height"]

    plots = {}
    cursor.execute("SELECT * FROM Plots")
    for row in cursor.fetchall():
        pid = row["ID"]
        x = pid % width
        y = pid // width
        plots[pid] = {
            "id": pid,
            "x": x,
            "y": y,
            "terrain": row["TerrainType"],
            "is_impassable": row["IsImpassable"],
            "feature": None,
            "resource": None,
            "rivers": []
        }

    cursor.execute("SELECT * FROM PlotFeatures")
    for row in cursor.fetchall():
        pid = row["ID"]
        if pid in plots:
            plots[pid]["feature"] = row["FeatureType"]

    cursor.execute("SELECT * FROM PlotResources")
    for row in cursor.fetchall():
        pid = row["ID"]
        if pid in plots:
            plots[pid]["resource"] = row["ResourceType"]

    cursor.execute("SELECT * FROM PlotRivers")
    for row in cursor.fetchall():
        pid = row["ID"]
        if pid in plots:
            # Rivers are on edges. Civ6Map format for rivers:
            # IsNEOfRiver, IsWOfRiver, IsNWOfRiver
            # These correspond to the three edges of the hex.
            if row["IsNEOfRiver"]: plots[pid]["rivers"].append("NE")
            if row["IsWOfRiver"]: plots[pid]["rivers"].append("W")
            if row["IsNWOfRiver"]: plots[pid]["rivers"].append("NW")

    conn.close()
    return {
        "width": width,
        "height": height,
        "plots": list(plots.values())
    }

if __name__ == "__main__":
    data = get_map_data('/data/maps/e2e_test_case_0.Civ6Map')
    with open('map_data.json', 'w') as f:
        json.dump(data, f)
